mapper.select:
select
    wom.*
from wms_outbound_manufactured wom
left join wms_outbound_detail_manufactured wodm on wom.id = wodm.outbound_manufactured_id and wodm.bool_delete_enum = 0
where wom.bool_delete_enum = 0

    and wom.serial_number like concat('%',#{serialNumber},'%')


    and (
        wom.applicant_name like concat('%',#{personName},'%')
        or
        wodm.recipient_name like concat('%',#{personName},'%')
    )


    and wodm.basic_class = #{basicClass}


    and wodm.project_id = #{projectId}


    
        and wom.applicant_time >= #{applicationTime[0]}
    
    
        and wom.applicant_time <= #{applicationTime[1]}
    


    
        and wom.review_pass_time >= #{reviewPassTime[0]}
    
    
        and wom.review_pass_time <= #{reviewPassTime[1]}
    


    and wodm.review_status = #{reviewStatus}

group by wom.id
